rm -f /etc/profile.d/autodarts-status.sh; lbu delete /etc/profile.d/autodarts-status.sh >/dev/null 2>&1 || true   # its old name
cat > /etc/profile.d/tikka-status.sh <<'EOF_STATUS'
[ -n "$PS1" ] || return 0
_ip=$(ip -4 addr show wlan0 2>/dev/null | sed -n 's/^ *inet \([^/]*\).*/\1/p')
_ssid=$(wpa_cli -i wlan0 status 2>/dev/null | sed -n 's/^ssid=//p')
_mhz=$(( $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_cur_freq) / 1000 ))
_temp=$(( $(cat /sys/class/thermal/thermal_zone0/temp) / 1000 ))
_eng=$(sed -n 's/^BOARD_ENGINE=//p' /data/scoreboard/data/settings 2>/dev/null | head -1)
_eng=${_eng:-autodarts}
_st=$(rc-service "$_eng" status 2>/dev/null | sed -n 's/.*status: //p')
case "$_eng" in tikka-vision) _name="Tikka Vision" ;; *) _name=Autodarts ;; esac
_volt=
for _h in /sys/class/hwmon/hwmon*; do [ "$(cat "$_h/name" 2>/dev/null)" = rpi_volt ] && [ "$(cat "$_h/in0_lcrit_alarm" 2>/dev/null)" = 1 ] && _volt=", UNDERVOLTAGE"; done
printf ' Board     : %s\n' "$(tr -d '\0' < /proc/device-tree/model)"
printf ' Network   : %s on %s\n' "${_ip:-no IP}" "${_ssid:-no Wi-Fi}"
printf ' CPU       : %s MHz, %s C%s\n' "$_mhz" "$_temp" "$_volt"
printf ' Scoring   : %s (%s)\n' "$_name" "${_st:-unknown}"
printf ' Time      : %s\n\n' "$(date '+%a %d.%m.%Y %H:%M')"
printf ' ad = board console (tk = Tikka Vision) | board-engine = switch program | net-reset = fix Wi-Fi | lbu commit -d = save\n\n'
unset _ip _ssid _mhz _temp _eng _st _name _volt _h
EOF_STATUS

lbu include /etc/motd /etc/profile.d/tikka-status.sh
lbu commit -d
echo "Done. Log in again to see it."
